data = Marshal.load(File.binread("tmp/test_prof/stack-prof-report-wall-raw-total.dump"))
total_samples = data[:samples].to_f
frames = data[:frames].values
puts "=== Top app/lib frames by total ==="
frames.select { |f| f[:file].include?("/app/") || (f[:file].include?("/lib/") && !f[:file].include?("/gems/") && !f[:file].include?("/ruby/")) }
      .sort_by { |f| -f[:total_samples] }.first(45)
      .each { |f| printf "%7d (%5.1f%%) | self %5d (%4.1f%%) | %s (%s:%s)\n", f[:total_samples], f[:total_samples]*100/total_samples, f[:samples], f[:samples]*100/total_samples, f[:name], f[:file].sub(Dir.pwd+"/", ""), f[:line] }

puts "\n=== Top spec frames by total ==="
frames.select { |f| f[:file].include?("/spec/") }
      .sort_by { |f| -f[:total_samples] }.first(25)
      .each { |f| printf "%7d (%5.1f%%) | self %5d (%4.1f%%) | %s (%s:%s)\n", f[:total_samples], f[:total_samples]*100/total_samples, f[:samples], f[:samples]*100/total_samples, f[:name], f[:file].sub(Dir.pwd+"/", ""), f[:line] }

puts "\n=== Top interesting gem frames (bcrypt/sidekiq/redis/openssl/paperclip/vips/nokogiri/chewy/devise/logger) ==="
frames.select { |f| f[:name] =~ /Sidekiq|BCrypt|OpenSSL|Paperclip|Vips|Redis|Devise|Logger|LogSubscriber|Chewy|Fabricat|DatabaseCleaner/i }
      .sort_by { |f| -f[:total_samples] }.first(35)
      .each { |f| printf "%7d (%5.1f%%) | self %5d (%4.1f%%) | %s (%s:%s)\n", f[:total_samples], f[:total_samples]*100/total_samples, f[:samples], f[:samples]*100/total_samples, f[:name], f[:file].sub(Dir.pwd+"/", ""), f[:line] }
'

